def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pairs = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 7:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((r, c, nr, nc, dr, dc, color))

    for r, c, nr, nc, dr, dc, color in pairs:
        for sr, sc, step in ((r, c, -1), (nr, nc, 1)):
            rr, cc = sr + step * dr, sc + step * dc
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] != 7:
                    break
                out[rr][cc] = color
                rr += step * dr
                cc += step * dc

    return out
